9: /// Target state to sync to.
10: ///
11: /// `PartialEq`, `Eq`, and `Clone` are implemented manually to avoid requiring `F` to implement
12: /// them.
13: #[derive(Debug)]
14: pub struct Target<F: Family, D: Digest> {
15:     /// The ops root the sync engine verifies streaming batches against.
16:     pub root: D,
17:     /// Range of operations to sync
18:     pub range: NonEmptyRange<Location<F>>,
19: }
20: 
21: impl<F: Family, D: Digest> Target<F, D> {
22:     /// Create a sync target.
23:     pub const fn new(root: D, range: NonEmptyRange<Location<F>>) -> Self {
24:         Self { root, range }
25:     }
26: 
27:     /// Whether this target advances relative to `from`.
28:     ///
29:     /// Both targets are assumed to describe valid states of the same append-only QMDB. Because
30:     /// the root commits to the database size, valid targets at different sizes have distinct
31:     /// roots.
32:     pub fn advances(&self, from: &Self) -> bool {
33:         self.range.end().is_valid()
34:             && self.range.end() > from.range.end()
35:             && self.range.start() >= from.range.start()
36:     }
37: }
38: 
39: impl<F: Family, D: Digest> Clone for Target<F, D> {
40:     fn clone(&self) -> Self {
41:         Self {
42:             root: self.root,
43:             range: self.range.clone(),
44:         }
45:     }
46: }
47: 
48: impl<F: Family, D: Digest> PartialEq for Target<F, D> {
49:     fn eq(&self, other: &Self) -> bool {
50:         self.root == other.root && self.range == other.range
51:     }
52: }
53: 
54: impl<F: Family, D: Digest> Eq for Target<F, D> {}
55: 
56: impl<F: Family, D: Digest> Write for Target<F, D> {
57:     fn write(&self, buf: &mut impl BufMut) {
58:         self.root.write(buf);
59:         self.range.write(buf);
60:     }
61: }
62: 
63: impl<F: Family, D: Digest> EncodeSize for Target<F, D> {
64:     fn encode_size(&self) -> usize {
65:         self.root.encode_size() + self.range.encode_size()
66:     }
67: }
68: 
69: impl<F: Family, D: Digest> Read for Target<F, D> {
70:     type Cfg = ();
71: 
72:     fn read_cfg(buf: &mut impl Buf, _: &()) -> Result<Self, CodecError> {
73:         let root = D::read(buf)?;
74:         let range = NonEmptyRange::<Location<F>>::read(buf)?;
75:         if !range.start().is_valid() || !range.end().is_valid() {
76:             return Err(CodecError::Invalid(
77:                 "storage::qmdb::sync::Target",
78:                 "range bounds out of valid range",
79:             ));
80:         }
81:         Ok(Self { root, range })
82:     }
83: }
