86: impl<F: Family, D: Digest> arbitrary::Arbitrary<'_> for Target<F, D>
87: where
88:     D: for<'a> arbitrary::Arbitrary<'a>,
89: {
90:     fn arbitrary(u: &mut arbitrary::Unstructured<'_>) -> arbitrary::Result<Self> {
91:         let root = u.arbitrary()?;
92:         let max_loc = F::MAX_LEAVES;
93:         let lower = u.int_in_range(0..=*max_loc - 1)?;
94:         let upper = u.int_in_range(lower + 1..=*max_loc)?;
95:         Ok(Self {
96:             root,
97:             range: commonware_utils::non_empty_range!(Location::new(lower), Location::new(upper)),
98:         })
99:     }
100: }
