189: // The unit tests use `MmrFamily` only. The codec and predicates are family-agnostic (the
190: // family only influences `Location::is_valid` via `F::MAX_LEAVES` and the `arbitrary` range
191: // picker), so an MMB variant would duplicate coverage. Codec conformance covers both families.
192: mod tests {
193:     use super::*;
194:     use crate::merkle::mmr::Family as MmrFamily;
195:     use commonware_codec::{DecodeExt as _, Encode as _};
196:     use commonware_cryptography::sha256;
