200:     fn target(root: sha256::Digest, start: u64, end: u64) -> Target<MmrFamily, sha256::Digest> {
201:         Target::new(
202:             root,
203:             non_empty_range!(Location::new(start), Location::new(end)),
204:         )
205:     }
