207:     #[test]
208:     fn test_sync_target_serialization() {
209:         let target = target(sha256::Digest::from([42; 32]), 100, 500);
210: 
211:         // Serialize
212:         let mut buffer = Vec::new();
213:         target.write(&mut buffer);
214: 
215:         // Verify encoded size matches actual size
216:         assert_eq!(buffer.len(), target.encode_size());
217: 
218:         // Deserialize
219:         let mut cursor = Cursor::new(buffer);
220:         let deserialized = Target::read(&mut cursor).unwrap();
221: 
222:         // Verify
223:         assert_eq!(target, deserialized);
224:         assert_eq!(target.root, deserialized.root);
225:         assert_eq!(target.range, deserialized.range);
226:     }
