228:     #[test]
229:     fn test_sync_target_read_invalid_bounds() {
230:         // Manually encode root + two Locations with reversed bounds
231:         let mut buffer = Vec::new();
232:         sha256::Digest::from([42; 32]).write(&mut buffer);
233:         Location::<MmrFamily>::new(100).write(&mut buffer); // start
234:         Location::<MmrFamily>::new(50).write(&mut buffer); // end (< start = invalid)
235: 
236:         let mut cursor = Cursor::new(buffer);
237:         assert!(matches!(
238:             Target::<MmrFamily, sha256::Digest>::read(&mut cursor),
239:             Err(CodecError::Invalid("NonEmptyRange", "start must be < end"))
240:         ));
241: 
242:         // Manually encode a target with an empty range (start == end)
243:         let root = sha256::Digest::from([42; 32]);
244:         let mut buffer = Vec::new();
245:         root.write(&mut buffer);
246:         Location::<MmrFamily>::new(100).write(&mut buffer);
247:         Location::<MmrFamily>::new(100).write(&mut buffer);
248: 
249:         let mut cursor = Cursor::new(buffer);
250:         assert!(matches!(
251:             Target::<MmrFamily, sha256::Digest>::read(&mut cursor),
252:             Err(CodecError::Invalid("NonEmptyRange", "start must be < end"))
253:         ));
