321:     #[test]
322:     fn test_compact_target_to_ranged() {
323:         let root = sha256::Digest::from([42; 32]);
324: 
325:         // The derived range replays the one operation ending at the target.
326:         let compact = CompactTarget::<MmrFamily, _> {
327:             root,
328:             size: Location::new(100),
329:         };
330:         let ranged = Target::try_from(&compact).unwrap();
331:         assert_eq!(ranged.root, root);
332:         assert_eq!(ranged.range.start(), Location::new(99));
333:         assert_eq!(ranged.range.end(), Location::new(100));
